import { assertSameOrigin, requireActor, requirePermission, revalidateActor } from '@/server/permissions';
import { apiError, json } from '@/server/http';
import { previewSitePackage, readPackageRequest } from '@/server/site-package';
export const runtime = 'nodejs';
export async function POST(request: Request) { try { assertSameOrigin(request); let actor = await requireActor(request); requirePermission(actor, 'manage'); const input = await readPackageRequest(request); /* 读完包体后才以最新权限开始只读预检。 */ actor = revalidateActor(actor, 'manage'); return json(await previewSitePackage(input)); } catch (e) { return apiError(e); } }
